CREATE TABLE im_accounts(id TEXT PRIMARY KEY, config TEXT NOT NULL, secret TEXT, bot_id TEXT, owner_id TEXT, base_url TEXT NOT NULL DEFAULT 'https://ilinkai.weixin.qq.com', cursor TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'unbound', error TEXT, updated_at INTEGER NOT NULL);
CREATE UNIQUE INDEX im_bot_account ON im_accounts(bot_id) WHERE bot_id IS NOT NULL;
CREATE TABLE im_conversations(account_id TEXT NOT NULL REFERENCES im_accounts(id) ON DELETE CASCADE, peer TEXT NOT NULL, session_id TEXT REFERENCES sessions(id) ON DELETE SET NULL, context_token TEXT NOT NULL, PRIMARY KEY(account_id,peer));
CREATE TABLE im_inbox(account_id TEXT NOT NULL REFERENCES im_accounts(id) ON DELETE CASCADE, message_id TEXT NOT NULL, peer TEXT NOT NULL, text TEXT NOT NULL, context_token TEXT NOT NULL, request_id TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', created_at INTEGER NOT NULL, PRIMARY KEY(account_id,message_id));
CREATE TABLE im_outbox(id TEXT PRIMARY KEY, account_id TEXT NOT NULL REFERENCES im_accounts(id) ON DELETE CASCADE, peer TEXT NOT NULL, context_token TEXT NOT NULL, source_key TEXT NOT NULL, text TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', error TEXT, created_at INTEGER NOT NULL, UNIQUE(account_id,peer,source_key));
